async function assertDock(side,p=page){await settleFloat(p);await p.waitForFunction(side=>{const b=tbBounds(),left=document.getElementById('tb-float').getBoundingClientRect().left;return Math.abs(left-(side==='left'?b.minX:b.maxX))<1;},side,{timeout:1000});const d=await p.evaluate(()=>({dock:timeBank.dock,x:timeBank.position.x,left:document.getElementById('tb-float').getBoundingClientRect().left,bounds:tbBounds()}));assert.equal(d.dock,side);assert.equal(d.x,side==='left'?0:1);assert(Math.abs(d.left-(side==='left'?d.bounds.minX:d.bounds.maxX))<1,'Timer must rest against the screen edge');}
async function call(ctx,url,body,method='POST'){const r=await ctx.fetch(base+'/api/'+url,{method,data:body});const d=await r.json();return {r,d};}
async function start(){base='http://127.0.0.1:8878';browser=await chromium.launch({...(edgeExecutable?{executablePath:edgeExecutable}:{}),headless:true});const newContext=browser.newContext.bind(browser);browser.newContext=async options=>{const c=await newContext(options);c.on('page',p=>p.on('response',r=>{const u=new URL(r.url());if(u.origin!==base||!u.pathname.startsWith('/api/'))return;const path=u.pathname.replace(/[a-f0-9]{8}-[a-f0-9-]{27,}/gi,'{id}');const key=r.request().method()+' '+path;const item=traffic.get(key)||{method:r.request().method(),path,statuses:{},requests:0};item.requests++;item.statuses[r.status()]=(item.statuses[r.status()]||0)+1;traffic.set(key,item);}));return c;};const context=await browser.newContext({viewport:{width:390,height:844},locale:'zh-CN'});page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));await page.goto(base+'/experience');await page.waitForFunction(()=>typeof px!=='undefined'&&px.loaded);}
