(async()=>{try{await run();}catch(e){results.push({name:'回归环境与执行',pass:false,error:e.stack});console.log('FATAL '+e.stack);}finally{if(browser)await browser.close();if(server){server.kill();await new Promise(r=>server.once('exit',r));}report.pass=results.length>0&&results.every(x=>x.pass);report.passed=results.filter(x=>x.pass).length;report.failed=results.filter(x=>!x.pass).length;report.browserApiEvidence=[...traffic.values()];fs.writeFileSync(path.join(__dirname,'Netlify适配接口实测证据.json'),JSON.stringify({at:report.at,scope:'真实浏览器发起请求的路径、方法及状态码汇总，不记录请求体、Cookie或凭据',items:report.browserApiEvidence},null,2),'utf8');report.buildHashes=Object.fromEntries(['东方智慧-首页体验R4.html','发给负责人-东方智慧首页R4.html','计时后台-开发联调.html'].map(name=>[name,fs.existsSync(path.join(web,name))?crypto.createHash('sha256').update(fs.readFileSync(path.join(web,name))).digest('hex'):null]));report.cloudBuildHashes=Object.fromEntries(['generated/experience.html','generated/admin.html','generated/review.html','lib/eastern-api.ts','worker/index.ts','worker/netlify-api.js','netlify.toml','prepare-netlify.mjs'].map(name=>[name,crypto.createHash('sha256').update(fs.readFileSync(path.join(source,'../cloud',name))).digest('hex')]));let history=[];if(fs.existsSync(reportFile))try{history=JSON.parse(fs.readFileSync(reportFile,'utf8')).runs||[];}catch{}history.push(report);fs.writeFileSync(reportFile,JSON.stringify({latest:report,runs:history.slice(-50)},null,2),'utf8');cleanDb();console.log(JSON.stringify({module:moduleName,pass:report.pass,passed:report.passed,failed:report.failed,report:reportFile}));process.exitCode=report.pass?0:1;}})();
